KG42.register("edges-a48d6e9cca66009ace545168",{"id":"S-ca5f9ef6f04df6db","source":"KG31-8571e493b8ecf84a","type":"links","target":"COMP-315d42da2c8d28d8","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["11-p2p_mechanisms_evaluation"],"assertions":[{"id":"11-p2p_mechanisms_evaluation::v141-c-R005::E::v141-c-R005-E002","paper":"11-p2p_mechanisms_evaluation","rule_id":"v141-c-R005","rule_ref":"11-p2p_mechanisms_evaluation::v141-c-R005","record":{"edge_id":"v141-c-R005-E002","source":"pricing.local","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R005-C003"],"evidence_ids":["v141-b-g01-e03"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R005-C003"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"KG31-8571e493b8ecf84a","target":"COMP-315d42da2c8d28d8","source_occurrence_id":"11-p2p_mechanisms_evaluation::v141-c-R005::V::pricing.local","target_occurrence_id":"11-p2p_mechanisms_evaluation::v141-c-R005::V::execution.energy_trade","source_unit_id":"11-p2p_mechanisms_evaluation::v141-a-M01::pricing.local","target_unit_id":"11-p2p_mechanisms_evaluation::v141-a-M01::execution.energy_trade","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"General P2P energy-sharing framework recorded under M01; trading within an energy sharing region. | General P2P paradigm recorded under M01; exchanges within the local market. | P2P energy sharing in grid-connected microgrids with one point of common coupling. | Simulation exit mechanism adopted in this paper; choice of trading arrangement upon termination. | Simulation exit mechanism attributed to Ref. [17]. | The aggregate retailer-trading paradigm shown in Fig. 2 for an energy sharing region.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e05","v141-b-g02-e15","v141-b-g02-e19"]},"active":true,"source_signature":"dca905ba4ce87a9c8a625a510710c40011a13e44ebf4fe96e9abecec73529233","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"Internal prices are tariff-bounded functions of the zone supply-demand ratio, with distinct buying/selling roles for net power signs. For SDR above one both equal the export tariff; for SDR between zero and one retain the source nonlinear selling-price formula and buying-price cost/balance construction. Do not generalize denominator limits or fee accounting beyond source conditions.","target_definition":"The energy sharing coordinator supervises the region's P2P energy-trading activities. Scope: General P2P energy-sharing framework recorded under M01; trading within an energy sharing region. The coordinator negotiates electricity purchases and sales with the retailer on behalf of the participants to balance energy within the region. Scope: The aggregate retailer-trading paradigm shown in Fig. 2 for an energy sharing region. Local P2P energy exchanges take place at the internal market price. Scope: General P2P paradigm recorded under M01; exchanges within the local market. Participants must first share energy with each other and then interact with the retailer through aggregated power. Scope: P2P energy sharing in grid-connected microgrids with one point of common coupling. Condition: The grid-connected microgrid has only one point of common coupling. P2P energy sharing is not used; all participants are instead considered to trade individually with the retailer. Scope: Simulation exit mechanism attributed to Ref. [17]. Condition: The maximum number of iterations is reached without convergence. P2P energy sharing remains in use based on the results of the last iteration. Scope: Simulation exit mechanism adopted in this paper; choice of trading arrangement upon termination. Condition: The simulation is forced to exit at the maximum number of iterations without convergence.","constraints":[{"constraint_id":"v141-c-R005-C003","kind":"procedural","role":"core","statement":"Local P2P energy exchanges take place at the internal market price. Scope: General P2P paradigm recorded under M01; exchanges within the local market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e03"]}],"evidence":[{"evidence_id":"v141-b-g01-e03","location":{"location_id":"src-d485825b0d-p04-c1r4__v141-a-M01-participation","page":4,"printed_page":"996","section":"3.1","anchor_text":"practice in many countries to set the export price in the FIT scheme co lower than the retail price.","equation_id":null,"figure_id":"Fig. 1","table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"In the P2P energy sharing paradigm, the prosumers and consumers first share their generation and consumption in a local market at an internal price, and then trade with a retailer to cover the remaining electricity deficit or surplus. The internal price is usually set between the export price and the retail price, so that each prosumer or consumer, no matter it is an electricity seller or buyer, benefits from the P2P energy sharing."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"General P2P energy-sharing framework recorded under M01; trading within an energy sharing region. | General P2P paradigm recorded under M01; exchanges within the local market. | P2P energy sharing in grid-connected microgrids with one point of common coupling. | Simulation exit mechanism adopted in this paper; choice of trading arrangement upon termination. | Simulation exit mechanism attributed to Ref. [17]. | The aggregate retailer-trading paradigm shown in Fig. 2 for an energy sharing region.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e05","v141-b-g02-e15","v141-b-g02-e19"]},"source_record":{"edge_id":"v141-c-R005-E002","source":"pricing.local","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R005-C003"],"evidence_ids":["v141-b-g01-e03"]},"paper_scope_note":"SDR, MMR, and BS are kept separate; the A18 net quantity differs from the A24 independent component; optional step-size control and the divergent loop in the example are not treated as general convergence or necessary dependencies."}}],"assertion_ids":["11-p2p_mechanisms_evaluation::v141-c-R005::E::v141-c-R005-E002"]});
